// GENERATED by `./gradlew generatePricingMutants` — do not edit by hand; edit the catalog.
//
// BASELINE: no mutation at all.
//
// Runs the selected suite against the UNMUTATED :core, to check the suite is valid in the
// first place. A suite that fails here contradicts the correct code, so it would "kill"
// every mutant with that same failure and its mutation score would be meaningless.

plugins {
    kotlin("jvm")
}

// Which suite runs against the mutant: "learner", or any test source dir given as a path
// relative to this build's root — set with -PmutantTests=<learner|path>. The default below
// is baked in per catalog at generation time, because -PmutantTests is global to the build
// and a build with two catalogs needs two different answers.
val suite: String = when (val selected = providers.gradleProperty("mutantTests").getOrElse("pricing-properties/kotlin")) {
    "learner" -> "../spec-test-driven/exercises/write-tests/src/test/kotlin"
    else -> selected
}

kotlin {
    jvmToolchain(21)

    sourceSets.named("main") {
        kotlin.srcDir(rootDir.resolve("reference/src/main/kotlin"))
        kotlin.srcDir(rootDir.resolve("../spec-test-driven/core/src/main/kotlin"))
        // no exclude: the baseline compiles the sources as they are
    }
    sourceSets.named("test") {
        kotlin.srcDir(rootDir.resolve(suite))
        // The mutants target the admission-policy algebra; schedule tests need the
        // implementation modules, which are deliberately not on this classpath.
        kotlin.exclude("**/schedule/**")
    }
}

repositories {
    mavenCentral()
}

dependencies {
    testImplementation(kotlin("test"))
}

tasks.test {
    useJUnitPlatform()
    // verifyMutants reads the XML results, so a killed mutant must not break the build.
    ignoreFailures = true
}
